-- The released file behind a document request, and the rule for handing it out.
--
-- A document is generated by a person (in the Document Maker, or from Zoho for
-- an invoice) and its final PDF is attached to the request by staff once the
-- request is Paid. The file lives in the private generated-documents bucket,
-- under the booking's id, which is the folder the bucket's policies key on.
-- Customers have no storage policy at all: they get a short-lived link from
-- the portal-download Edge Function, and only if document_release_blocked_reason
-- says nothing is blocking it.
--
-- document_versions cannot carry this: its doc_type check lists the documents
-- the Document Maker draws (bl, cro, onboard, can, do, offloading) and not the
-- OBL copies, surrender BL or other documents a customer can ask for.

alter table public.document_requests
  add column if not exists released_file_path text,
  add column if not exists released_file_name text,
  add column if not exists released_at timestamptz,
  add column if not exists released_by text;

-- "Generated" now means a file has been attached, by either route.
create or replace function public.document_release_blocked_reason(p_request uuid)
returns text
language plpgsql stable security definer set search_path to 'public'
as $fn$
declare
  v_req public.document_requests%rowtype;
  v_paid boolean;
begin
  select * into v_req from public.document_requests where id = p_request;
  if not found then
    return 'That document request does not exist.';
  end if;

  if v_req.status = 'Rejected' then
    return coalesce('This request was rejected: ' || v_req.reject_reason, 'This request was rejected.');
  end if;

  if v_req.status in ('Submitted', 'Under review') then
    return 'This request has not been approved yet.';
  end if;

  -- Gate 2: the document's OWN invoice.
  select exists (
    select 1 from public.invoices i
     where i.document_request_id = v_req.id
       and i.paid_at is not null
  ) into v_paid;

  if not v_paid then
    return 'The invoice for this document has not been paid yet.';
  end if;

  if v_req.document_version_id is null and v_req.released_file_path is null then
    return 'The document has not been generated yet.';
  end if;

  -- Null means nothing is blocking it.
  return null;
end
$fn$;

-- Staff attach the final file to a Paid request, which releases it.
create or replace function public.release_document_request(p_request uuid, p_path text, p_file_name text)
returns void
language plpgsql security definer set search_path to 'public'
as $fn$
declare
  v_req public.document_requests%rowtype;
  v_me  text;
  v_why text;
begin
  if not public.is_staff() then
    raise exception 'Only staff can release a document.' using errcode = 'insufficient_privilege';
  end if;

  select * into v_req from public.document_requests
   where id = p_request and tenant_id = public.auth_tenant_id() for update;
  if not found then
    raise exception 'That document request does not exist.' using errcode = 'no_data_found';
  end if;
  if v_req.status not in ('Paid', 'Ready to download') then
    raise exception 'The request is %; a file is attached only once it is Paid.', v_req.status
      using errcode = 'restrict_violation';
  end if;

  -- The file must sit in this booking's folder, or the bucket's own rules
  -- would not apply to it, and it must really be there.
  if (storage.foldername(p_path))[1] is distinct from v_req.booking_id::text then
    raise exception 'The file must be stored under this booking.' using errcode = 'restrict_violation';
  end if;
  if not exists (select 1 from storage.objects where bucket_id = 'generated-documents' and name = p_path) then
    raise exception 'That file has not been uploaded.' using errcode = 'restrict_violation';
  end if;

  select name into v_me from public.profiles where id = auth.uid();

  update public.document_requests
     set released_file_path = p_path,
         released_file_name = nullif(trim(p_file_name), ''),
         released_at = now(),
         released_by = coalesce(v_me, 'staff')
   where id = p_request;

  v_why := public.document_release_blocked_reason(p_request);
  if v_why is not null then
    raise exception '%', v_why using errcode = 'restrict_violation';
  end if;

  update public.document_requests set status = 'Ready to download' where id = p_request;
end
$fn$;
